else: ?><section><div class="wrap"><?php if(is_post_type_archive('pt_project'))pt_filter_topics('pt_application','industry','Industry'); ?><div class="content-grid"><?php if(have_posts()):while(have_posts()):the_post(); ?><article><?php if(has_post_thumbnail())the_post_thumbnail('medium'); ?><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><p><?php echo esc_html(get_the_excerpt()); ?></p><a class="text-link" href="<?php the_permalink(); ?>">Explore solution →</a></article><?php endwhile;else: ?><div class="empty-state"><h2>Content is being prepared</h2><p>Approved projects and case studies will appear here.</p></div><?php endif; ?></div><?php the_posts_pagination(); ?></div></section><?php if(is_post_type_archive('pt_service')){echo '<section class="pale"><div class="wrap"><h2>From Sourcing to Delivery</h2>';get_template_part('steps');echo '</div></section>';}pt_cta();endif;get_footer(); ?>
